return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-06 01:48+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Plagin qidiruviga o&#39;ting','Activate %s' => '%s faollashtirish','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> oʻrnatilishi va faollashishi uchun <strong>%2$s</strong> talab qilinadi. <a href="%4$s">%3$s</a>','Enter your code here' => 'Kodingizni shu yerga kiriting','Add %s' => '%s qo‘shing','Remove' => 'O&#39;chirish','Order number and receipt will be sent to this email address.' => 'Buyurtma raqami va kvitansiya ushbu elektron pochta manziliga yuboriladi.','Apartment, unit, building, floor, etc.' => 'Kvartira, birlik, bino, qavat va boshqalar.','Shipping phone' => 'Yuk tashish telefoni','Only used for shipping-related questions.' => 'Faqat yuk tashish bilan bog&#39;liq savollar uchun ishlatiladi.','Single step' => 'Yagona qadam','Click to go to the order summary' => 'Buyurtma xulosasiga o&#39;tish uchun bosing','Cart total:' => 'Savat jami:','Proceed to %s' => '%s ga o‘ting','Proceed to contact' => 'Aloqa uchun davom eting','Proceed to shipping' => 'Yuk tashishga o&#39;ting','Proceed to billing' => 'Hisob-kitobga o&#39;ting','Proceed to payment' => 'To&#39;lovga o&#39;ting','Shipping method' => 'Yuk tashish usuli','Additional notes' => 'Qo&#39;shimcha eslatmalar','Payment method' => 'To&#39;lov usuli','Step %1$s of %2$s' => '%1$s qadam / %2$s','Change: %s' => 'Oʻzgartirish: %s','Not selected yet.' => 'Hali tanlanmagan.','Same as shipping address' => 'Yuk tashish manzili bilan bir xil','Same as billing address' => 'Hisob-kitob manzili bilan bir xil','Order summary' => 'Buyurtma xulosasi','Edit cart' => 'Savatni tahrirlash','Did you mean %s?' => '%sni nazarda tutdingizmi?','Change email address to: {suggestion-value}' => 'Elektron pochta manzilini {suggestion-value} ga oʻzgartiring','This is a required field.' => 'Bu talab qilinadigan maydon.','This is not a valid email address.' => 'Bu yaroqli elektron pochta manzili emas.','This field does not match the related field value.' => 'Bu maydon tegishli maydon qiymatiga mos kelmaydi.','The CPF number "{cpf_number}" is invalid.' => '&quot;{cpf_number}&quot; CPF raqami yaroqsiz.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ raqami &quot;{cnpj_number}&quot; yaroqsiz.','(Required)' => '(majburiy)','Checkout Header - Desktop' => 'Hisob-kitob sarlavhasi - Ish stoli','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Katta ekranlar uchun to&#39;lov sarlavhasida vidjetlarni ko&#39;rsatish. Faqat plaginning to&#39;lov sarlavhasidan foydalanilganda ko&#39;rsatiladi.','Checkout Header - Mobile' => 'Hisob-kitob sarlavhasi - Mobil','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Vidjetlarni mobil qurilmalar uchun to‘lov sarlavhasi ostida ko‘rsatish. Faqat plaginning to&#39;lov sarlavhasidan foydalanilganda ko&#39;rsatiladi.','Checkout Sidebar' => 'Tekshirish yon paneli','Display widgets on the checkout sidebar after the order summary.' => 'Buyurtma sarhisobidan keyin to&#39;lov yon panelida vidjetlarni ko&#39;rsatish.','Checkout Order Summary' => 'To&#39;lov buyurtmasi haqida xulosa','Display widgets inside the order summary at the checkout page.' => 'Vidjetlarni to‘lov sahifasida buyurtma xulosasi ichida ko‘rsatish.','Checkout Below Place Order' => 'Buyurtmani joylashtirish ostidagi to&#39;lov','Display widgets below the place order button at the checkout page.' => 'Toʻlov sahifasida “Buyurtma berish” tugmasi ostidagi vidjetlarni koʻrsating.','Checkout Footer' => 'Tekshirish altbilgisi','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Vidjetlarni to‘lovning pastki qismida ko‘rsatish. Faqat plaginning to&#39;lov kolontiteridan foydalanilganda ko&#39;rsatiladi.','Classic' => 'Klassik','Boxed' => 'Qutili','Split' => 'Split','Minimalist' => 'Minimalist','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'CodeRockz tomonidan Fluid Checkout va Delivery Date plaginlari','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>CodeRockz tomonidan WooCommerce (bepul va PRO) uchun Delivery &amp; Pickup Date Time plaginlaridan foydalanayotganingizni aniqladik. Ushbu plaginlar bilan integratsiya Fluid Checkout PRO-ga ko&#39;chirildi.</p>','Upgrade to PRO' => 'PRO ga yangilang','Fluid Checkout database updated successfully' => 'Fluid Checkout ma&#39;lumotlar bazasi muvaffaqiyatli yangilandi','The database changes where applied successfully.' => 'Ma&#39;lumotlar bazasi muvaffaqiyatli qo&#39;llanilganda o&#39;zgaradi.','Dismiss' => 'Rad etish','Fluid Checkout database update' => 'Fluid Checkout ma&#39;lumotlar bazasi yangilanishi','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Ma&#39;lumotlar bazasiga ba&#39;zi o&#39;zgarishlar kiritilishi kerak. Har qanday yangilanishda bo&#39;lgani kabi, <strong>davom etishdan oldin veb-saytingizning to&#39;liq zaxira nusxasini olishingizni</strong> tavsiya qilamiz.','Update database' => 'Ma&#39;lumotlar bazasini yangilash','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout Divi Builder hisob-kitob tartibiga mos kelmaydi','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout ishlashi uchun klassik WooCommerce qisqa kodiga asoslangan hisob-kitob shakli kerak. Hisob-kitob sahifasining ko&#39;rinishi va hissiyotini sozlash uchun Divi Builder-dan foydalanilganda, klassik qisqa kodlar to&#39;lov sahifasining har bir qismi uchun Divi Builder-dan maxsus vidjetlar bilan almashtiriladi. Ushbu maxsus vidjetlar Fluid Checkout bilan mos kelmaydi.</p><p> Iltimos, Divi Builder vidjetlarini <code>[woocommerce_checkout]</code> qisqa kodini oʻz ichiga olgan matnli vidjet bilan almashtirib, toʻlov sahifangizni tahrirlang.</p>','Edit the checkout page' => 'Hisob-kitob sahifasini tahrirlang','Read the documentation.' => 'Hujjatlarni o&#39;qing.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Fluid Checkout-dan foydalanganda nemislashtirilgan PRO ko&#39;p bosqichli to&#39;lov funksiyasi o&#39;chirib qo&#39;yilishi kerak','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Fluid Checkout-dan foydalanilganda, Germanized PRO plaginining ko&#39;p bosqichli xususiyati keraksiz bo&#39;lib qoladi va <strong>yangi buyurtmalarni qayta ishlashda jiddiy xatolarga</strong> olib kelishi mumkin. Iltimos, plagin sozlamalarida Germanized PRO ko‘p bosqichli to‘lov funksiyasini o‘chirib qo‘ying.','Go to Germanized settings' => 'Nemislashtirilgan sozlamalarga o&#39;ting','Thanks for choosing Fluid Checkout!' => 'Fluid Checkout xizmatini tanlaganingiz uchun tashakkur!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Siz plagindan anchadan beri foydalanyapsiz. Hozirgacha bu sizga qanday yoqadi?<br> Iltimos, bizga tezkor baho bering, biz har bir fikr-mulohazani qadrlaymiz va bu bizni plaginni yaxshilashda davom etishga undaydi :)','Rate the plugin' => 'Plaginni baholang','I need help!' => 'Menga yordam kerak!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Quadlayers tomonidan WooCommerce Checkout Manager-ning ba&#39;zi xususiyatlari uni Fluid Checkout bilan ishlatganda kutilganidek ishlamasligi mumkin. Qo&#39;shimcha ma&#39;lumot va muqobil echimlar uchun <a href="%s">hujjatlarimizni</a> o&#39;qing.','Read documentation' => 'Hujjatlarni o&#39;qing','Don\'t show this again' => 'Buni boshqa ko&#39;rsatma','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Ko&#39;proq dizayn shablonlari','Optimized cart page' => 'Optimallashtirilgan savat sahifasi','Optimized order received / thank you page' => 'Optimallashtirilgan buyurtma qabul qilindi / rahmat sahifasi','Edit cart contents at checkout page' => 'To&#39;lov sahifasida savat tarkibini tahrirlang','Account matching / user matching' => 'Hisobni moslashtirish / foydalanuvchini moslashtirish','Trust symbols on the cart and thank you pages' => 'Savatdagi ishonch belgilari va rahmat sahifalari','More positions for the coupon code on the checkout page' => 'To&#39;lov sahifasida kupon kodi uchun ko&#39;proq pozitsiyalar','International phone numbers' => 'Xalqaro telefon raqamlari','Gift messages and packing slips' => 'Sovg&#39;a xabarlari va qadoqlash varaqlari','Local pickup and in-store collection' => 'Mahalliy olib ketish va do&#39;konda yig&#39;ish','EU-VAT Assistant' => 'EI-QQS yordamchisi','I already have it – Hide this offer' => 'Menda allaqachon bor - bu taklifni yashirish','Activated' => 'Faollashtirilgan','Address book' => 'Manzil kitobi','Select an image' => 'Rasm tanlang','Cart layout' => 'Arava tartibi','Cart optimizations' => 'Savatni optimallashtirish','Enable cart page optimizations' => 'Savat sahifalarini optimallashtirishni yoqing','Header and footer template' => 'Sarlavha va altbilgi shabloni','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Chalg‘itmaydigan sahifa sarlavhasi va altbilgisidan foydalanish yoki hozirda faol mavzuning sarlavha va altbilgisini saqlashni boshqaradi.','Distraction free header and footer' => 'Chalg&#39;itmasdan sarlavha va altbilgi','Theme\'s header and footer' => 'Mavzuning sarlavhasi va altbilgisi','Cart elements' => 'Arava elementlari','Make the order summary stay visible on the cart page while scrolling' => 'Buyurtma sarlavhasi aylanayotganda savat sahifasida ko&#39;rinadigan qilib qo&#39;ying','Coupon codes' => 'Kupon kodlari','Hidden' => 'Yashirin','Before the cart items section' => 'Arava buyumlari bo&#39;limidan oldin','Inside the cart items section' => 'Savat buyumlari bo&#39;limi ichida','After the cart items section' => 'Savatchalar bo&#39;limidan keyin','Before the shipping section' => 'Yuk tashish bo&#39;limidan oldin','After the shipping section' => 'Yuk tashish bo&#39;limidan keyin','Before the order summary' => 'Buyurtma xulosasidan oldin','Inside the order summary' => 'Buyurtma xulosasi ichida','Before the order totals' => 'Buyurtma summasidan oldin','After the order totals' => 'Buyurtma yig&#39;indisidan keyin','After the order summary' => 'Buyurtma xulosasidan keyin','Shipping' => 'yuk tashish; yetkazib berish','Select position where to display the shipping costs and calculator on the cart page.' => 'Savat sahifasida yuk narxi va kalkulyator ko&#39;rsatiladigan joyni tanlang.','Display as a cart section' => 'Savat qismi sifatida ko&#39;rsatish','Cross-sells' => 'O&#39;zaro sotuvlar','Select position where to display the cross-sells section on the cart page.' => 'Savat sahifasida o&#39;zaro sotuvlar bo&#39;limi ko&#39;rsatiladigan joyni tanlang.','Before the cart actions' => 'Arava harakatlaridan oldin','After the cart actions' => 'Arava harakatlaridan keyin','Layout of cross-sell items on the cart page.' => 'Savat sahifasida o&#39;zaro sotiladigan mahsulotlarning joylashuvi.','Optimized horizontal cross-sells layout' => 'Optimallashtirilgan gorizontal o&#39;zaro savdo tartibi','Theme\'s cross-sells layout' => 'Mavzuning o&#39;zaro savdo tartibi','Number of cross-sell items to display on the cart page' => 'Savat sahifasida ko&#39;rsatiladigan o&#39;zaro sotiladigan narsalar soni','Add widget areas to the cart page' => 'Savat sahifasiga vidjet maydonlarini qo&#39;shing','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Ushbu vidjet maydonlari arava sahifasiga ishonch belgilari va ishonch nishonlarini qo&#39;shish uchun ishlatiladi.','Checkout' => 'Ro&#39;yxatdan o&#39;chirilish','Checkout layout' => 'Chiqish tartibi','Design template' => 'Dizayn shablon','Dark mode' => 'Qorong&#39;i rejim','Enable dark mode' => 'Qorong&#39;i rejimni yoqing','Logo image' => 'Logotip tasviri','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'To&#39;lov sahifasi sarlavhasida ko&#39;rsatiladigan rasmni tanlang. Faqat chalg&#39;itmaydigan sarlavha va altbilgidan foydalanganda amal qiladi.','Header background color' => 'Sarlavha fon rangi','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Hisob-kitob sahifasi sarlavhasi uchun fon rangini tanlang. Faqat chalg&#39;itmaydigan sarlavha va altbilgidan foydalanganda amal qiladi.','HTML color value. ie: #f3f3f3' => 'HTML rang qiymati. ya&#39;ni: #f3f3f3','Page background color' => 'Sahifa fon rangi','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Hisob-kitob sahifasi uchun fon rangini tanlang. Rang <em>tananing</em> elementiga qo&#39;llaniladi.','Footer background color' => 'Altbilgi fon rangi','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Hisob-kitob sahifasi altbilgisi uchun fon rangini tanlang. Faqat chalg&#39;itmaydigan sarlavha va altbilgidan foydalanganda amal qiladi.','Progress bar' => 'Rivojlanish paneli','Display the checkout progress bar when using multi-step checkout layout' => 'Ko&#39;p bosqichli to&#39;lov tartibidan foydalanganda to&#39;lov jarayoni satrini ko&#39;rsating','Make the checkout progress bar stay visible while scrolling' => 'Oʻtkazish paytida toʻlov jarayoni satri koʻrinadigan boʻlsin','Express checkout' => 'Ekspress to&#39;lov','Enable the express checkout section' => 'Ekspress to&#39;lov bo&#39;limini yoqing','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Qo&#39;llab-quvvatlanadigan to&#39;lov shlyuzlarida bu xususiyat yoqilgan bo&#39;lsa, to&#39;lov vaqtida tezkor to&#39;lov bo&#39;limini ko&#39;rsatadi.','Display express checkout buttons in one line for larger screens' => 'Kattaroq ekranlar uchun tezkor to&#39;lov tugmalarini bir qatorda ko&#39;rsating','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Mos keladigan tezkor to&#39;lov shlyuzi bilan to&#39;lashda qo&#39;shimcha to&#39;lov talab qilinadigan maydonlarga e&#39;tibor bermang','Make the order summary stay visible while scrolling' => 'O&#39;tkazish paytida buyurtma xulosasini ko&#39;rinadigan qilib qo&#39;ying','Choose a background color for the order summary section.' => 'Buyurtma xulosasi bo&#39;limi uchun fon rangini tanlang.','Highlight the order totals row in the order summary table' => 'Buyurtmalar sarhisobi jadvalidagi buyurtma jami qatorini ajratib ko&#39;rsating','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Buyurtma xulosasi bo&#39;limida ta&#39;kidlangan fon rangi bo&#39;lmasa, eng foydali bo&#39;ladi. Fluid Checkout PRO-dan foydalanganda Savat, Qabul qilingan buyurtma va Buyurtmani ko&#39;rish sahifalariga ham tegishli bo&#39;lishi mumkin.','Action link on the order summary at checkout.' => 'To‘lov vaqtida buyurtma xulosasidagi amallar havolasi.','Edit cart link' => 'Savatga havolani tahrirlash','Cart items count' => 'Savatdagi buyumlar soni','Link to shop page' => 'Do&#39;kon sahifasiga havola','Cart items' => 'Savat buyumlari','Hide cart items errors at the checkout page' => 'To&#39;lov sahifasida savatdagi xatolarni yashirish','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'To&#39;lov sahifasining yuqori qismida savat elementlari xato xabarini ko&#39;rsatmang. Xaridni yakunlash uchun to&#39;lov shaklini yuborayotganda, bu xato xabarlari doimo ko&#39;rsatiladi.','Place order' => 'Buyurtma berish','Define the position to display "Place order" and terms checkbox section.' => '&quot;Buyurtmani joylashtirish&quot; va shartlarni belgilash katakchasini ko&#39;rsatadigan joyni belgilang.','Some options might not be compatible with some plugins and themes.' => 'Ba&#39;zi variantlar ba&#39;zi plaginlar va mavzular bilan mos kelmasligi mumkin.','Below the payment section' => 'To&#39;lov bo&#39;limi ostida','Below the order summary' => 'Buyurtma xulosasi ostida','Both below the payment section and the order summary' => 'Toʻlov boʻlimi va buyurtma xulosasi ostida','Add widget areas to the checkout page' => 'Hisob-kitob sahifasiga vidjet maydonlarini qo&#39;shing','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Ushbu vidjet maydonlari to&#39;lov sahifasiga ishonch belgilari va ishonch nishonlarini qo&#39;shish uchun ishlatiladi.','Display the coupon codes section title' => 'Kupon kodlari bo&#39;limi sarlavhasini ko&#39;rsating','Select position where to display the coupon codes section on the checkout page.' => 'To&#39;lov sahifasida kupon kodlari bo&#39;limi ko&#39;rsatiladigan joyni tanlang.','Before the checkout steps' => 'To&#39;lov bosqichlaridan oldin','As a substep before payment methods' => 'To&#39;lov usullaridan oldin kichik qadam sifatida','As a substep after payment methods' => 'To&#39;lov usullaridan keyin pastki qadam sifatida','Default button style' => 'Standart tugma uslubi','"Add" link button' => '&quot;Qo&#39;shish&quot; havola tugmasi','Checkout fields' => 'Hisob-kitob maydonlari','Optional fields' => 'Ixtiyoriy maydonlar','Hide optional fields behind a link button' => 'Ixtiyoriy maydonlarni havola tugmasi orqasiga yashiring','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Ochiq kirish maydonlari sonini kamaytirish uchun ushbu parametrni belgilab qo&#39;yish tavsiya etiladi, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">tadqiqotni o&#39;qing</a> .','Do not hide "Address line 2" fields behind a link button' => 'Bog&#39;lanish tugmasi orqasida &quot;Manzil qatori 2&quot; maydonlarini yashirmang','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Aksariyat mijozlarga “Manzil qatori 2” maydoni kerak bo‘lganda yoki to‘g‘ri yetkazib berish manzili muhim bo‘lganda (ya’ni, oziq-ovqat va boshqa tez buziladigan mahsulotlarni yetkazib berishda) tavsiya etiladi.','Billing address' => 'To&#39;lovchi; to&#39;lovni qabul qiladigan manzil','Select position where to display the billing address section on the checkout page.' => 'To‘lov sahifasida to‘lov manzili bo‘limi ko‘rsatiladigan joyni tanlang.','As a step before shipping' => 'Yuk tashishdan oldin qadam sifatida','As a sub-step before the shipping address section' => 'Yuk tashish manzili bo&#39;limidan oldingi kichik qadam sifatida','As a sub-step after the shipping address section' => 'Yuk tashish manzili bo&#39;limidan keyin pastki bosqich sifatida','As a step after shipping' => 'Yuk tashishdan keyingi qadam sifatida','As a sub-step before the payment section' => 'To&#39;lov bo&#39;limidan oldingi kichik qadam sifatida','Force billing and shipping addresses to the same (single section)' => 'To‘lov va yetkazib berish manzillarini bir xil (bitta bo‘lim) ga majburlash','Checkbox for "Same as shipping/billing address" checked by default' => 'Sukut bo&#39;yicha &quot;Yuk tashish/to&#39;lov manzili bilan bir xil&quot; katagiga belgi qo&#39;yilgan','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Yuk tashish manzili bo&#39;limi birinchi bo&#39;lib ko&#39;rsatilganda &quot;Yuk tashish manzili bilan bir xil&quot; katakchasi sukut bo&#39;yicha belgilangan tarzda boshlanadi.<br> Hisob-kitob manzili bo&#39;limi birinchi bo&#39;lib ko&#39;rsatilganda, &quot;To&#39;lov manzili bilan bir xil&quot; katakchasi sukut bo&#39;yicha belgilangan tarzda boshlanadi.<br> To&#39;lov paytida ochiq kirish maydonlari sonini sezilarli darajada kamaytirish uchun ushbu parametrni belgilab qo&#39;yish tavsiya etiladi, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">tadqiqotni o&#39;qing</a> .','Highlight the billing address section in the checkout form' => 'To&#39;lov shaklida to&#39;lov manzili bo&#39;limini belgilang','Shipping address' => 'Yetkazib berish manzili','Highlight the shipping address section in the checkout form' => 'To&#39;lov shaklida etkazib berish manzili bo&#39;limini belgilang','Shipping methods' => 'Yuk tashish usullari','Choose in which position to display the shipping methods section.' => 'Yuk tashish usullari bo&#39;limini qaysi holatda ko&#39;rsatishni tanlang.','Before shipping address' => 'Yuk tashish manzilidan oldin','After shipping address' => 'Yuk tashish manzilidan keyin','Local pickup' => 'Mahalliy olib ketish','Removes shipping address section when a local pickup shipping method is selected.' => 'Mahalliy olib ketish usuli tanlanganda yetkazib berish manzili boʻlimini olib tashlaydi.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Mahalliy olib ketish usuli tanlanganda jo‘natish manzilini qabul qilish punkti joyi bilan almashtiradi.','Choose which address to save as the shipping address for local pickup orders.' => 'Mahalliy olib ketish buyurtmalari uchun yuk manzili sifatida saqlash uchun qaysi manzilni tanlang.','Save the selected pickup location' => 'Tanlangan olib ketish joyini saqlang','Save same as the billing address' => 'Hisob-kitob manzili bilan bir xil saqlang','Do not save any shipping address' => 'Hech qanday yuk manzilini saqlamang','Company name field for shipping address' => 'Yuk tashish manzili uchun kompaniya nomi maydoni','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Hisob-kitob shaklidagi etkazib berish manzili bo&#39;limi uchun kompaniya nomi maydonining ko&#39;rinishini o&#39;zgartiring.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Agar maydon standart koʻrinish holati boʻlgan “ixtiyoriy” sifatida sozlangan boʻlsa, boshqa plaginlarga kerakli oʻzgarishlarni qoʻllash uchun hech qanday oʻzgarishlar qoʻllanilmaydi.','Hidden (remove field)' => 'Yashirin (maydonni olib tashlash)','Optional' => 'Ixtiyoriy','Required' => 'Majburiy','Add shipping phone field to the checkout form.' => 'To‘lov shakliga jo‘natma telefoni maydonini qo‘shing.','Choose in which step to display the shipping phone field.' => 'Yuborilgan telefon maydonini qaysi bosqichda ko&#39;rsatishni tanlang.','Contact step' => 'Aloqa bosqichi','Billing phone' => 'Hisob-kitob telefoni','Add billing phone field to the checkout form.' => 'To‘lov shakliga billing telefon maydonini qo‘shing.','Choose in which step to display the billing phone field.' => 'Billing telefon maydonini qaysi bosqichda ko&#39;rsatishni tanlang.','Show country code beside the flag' => 'Bayroq yonida mamlakat kodini ko&#39;rsating','Show an example of a valid phone number inside phone fields' => 'Telefon maydonlarida haqiqiy telefon raqamiga misol ko&#39;rsating','Do not change placeholders' => 'To&#39;ldiruvchilarni o&#39;zgartirmang','Show if not defined' => 'Belgilanmagan bo&#39;lsa ko&#39;rsating','Always show' => 'Har doim ko&#39;rsating','Order notes' => 'Buyurtma eslatmalari','Define the visibility of the additional order notes field.' => 'Qo&#39;shimcha buyurtma eslatmalari maydonining ko&#39;rinishini belgilang.','Gift options' => 'Sovg&#39;a variantlari','Allow customers to add a gift message and other gift related options to the order.' => 'Mijozlarga sovg&#39;a xabari va sovg&#39;a bilan bog&#39;liq boshqa variantlarni buyurtmaga qo&#39;shishga ruxsat bering.','Display the gift message as part of the order details table instead of a separate section' => 'Sovg&#39;a xabarini alohida bo&#39;lim o&#39;rniga buyurtma tafsilotlari jadvalining bir qismi sifatida ko&#39;rsating','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Ushbu parametr buyurtmani tasdiqlash sahifasiga (rahmat sahifasi) va hisob sahifalari, elektron pochta xabarlari va qadoqlash varaqlaridagi buyurtma tafsilotlariga ta&#39;sir qiladi.','Account matching' => 'Hisobni moslashtirish','Enable the account matching feature' => 'Hisobni moslashtirish funksiyasini yoqing','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Mijozning aloqa ma&#39;lumotlari bilan hisob allaqachon mavjud bo&#39;lsa, mehmon mijozning buyurtmalarini ularning mavjud hisobi bilan bog&#39;lang.','Display message when an account exists with the email address provided' => 'Ko&#39;rsatilgan elektron pochta manzili bilan hisob mavjud bo&#39;lganda xabarni ko&#39;rsatish','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Hisob yaratish maydonlarini bildirishnoma va tizimga kirish opsiyasi bilan almashtiradi. Baʼzi kontekstlarda mijozlarning maxfiyligini himoya qilish uchun ushbu parametrni oʻchirib qoʻyish tavsiya etilishi mumkin.','Dashboard' => 'Boshqaruv paneli','Integrations' => 'Integratsiyalar','License keys' => 'Litsenziya kalitlari','Visit our website for more information about our plugins and add-ons.' => 'Plaginlarimiz va plaginlarimiz haqida ko&#39;proq ma&#39;lumot olish uchun veb-saytimizga tashrif buyuring.','Order pay page' => 'Buyurtma to&#39;lash sahifasi','Order pay' => 'Buyurtma to&#39;lash','Enable order pay page optimizations' => 'Buyurtma toʻlovi sahifasini optimallashtirishni yoqing','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Mijozdan toʻlov kutilayotgan mavjud buyurtmalar uchun toʻlov sahifasi tartibini oʻzgartiradi.','Add widget areas to the order pay page' => 'Buyurtmani to&#39;lash sahifasiga vidjet maydonlarini qo&#39;shing','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Bu vidjet maydonlari buyurtma toʻlovi sahifasiga ishonch belgilari va ishonch nishonlarini qoʻshish uchun ishlatiladi.','Thank you page & order details layout' => 'Rahmat sahifasi va buyurtma tafsilotlari tartibi','Order details optimizations' => 'Buyurtma tafsilotlarini optimallashtirish','Enable thank you page and order details optimizations' => 'Rahmat sahifasi va buyurtma tafsilotlarini optimallashtirishni yoqing','Changes the layout of order details on the thank you page and account pages.' => 'Rahmat sahifasi va hisob sahifalarida buyurtma tafsilotlari tartibini o&#39;zgartiradi.','Enable order details customizations on email notifications' => 'Elektron pochta xabarnomalarida buyurtma tafsilotlarini sozlashni yoqing','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Elektron pochta xabarnomalarida yangi bo&#39;limlarni ko&#39;rsatish va bo&#39;limlar tartibini o&#39;zgartirish. Elektron pochta xabarnomalarida buyurtma tafsilotlari uslublari o&#39;zgarishsiz qoladi.','Thank you page' => 'Rahmat sahifasi','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Ushbu parametrlar buyurtma qabul qilingan yoki buyurtmani tasdiqlash sahifalari sifatida ham tanilgan rahmat sahifasiga ta&#39;sir qiladi.','Order details layout' => 'Buyurtma tafsilotlari tartibi','Display the order details with wide layout on the thank you page' => 'Rahmat sahifasida buyurtma tafsilotlarini keng tartib bilan ko&#39;rsating','Add widget areas to the thank you page' => 'Minnatdorchilik sahifasiga vidjet maydonlarini qo&#39;shing','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Ushbu vidjet maydonlari rahmat sahifasiga ishonch belgilari va ishonch nishonlarini qo&#39;shish uchun ishlatiladi.','Order actions' => 'Amallarni buyurtma qilish','Choose in which position to display the order actions.' => 'Buyurtma harakatlarini qaysi holatda ko&#39;rsatishni tanlang.','Inside the order overview' => 'Buyurtmaning umumiy ko&#39;rinishi ichida','After the order overview' => 'Buyurtmani ko&#39;rib chiqqandan so&#39;ng','After order sections' => 'Buyurtma bo&#39;limlaridan keyin','Order status' => 'Buyurtma holati','Display the order status progress bar' => 'Buyurtma holatining borishi satrini ko&#39;rsating','Choose in which position to display the section.' => 'Bo&#39;limni qaysi holatda ko&#39;rsatishni tanlang.','After the order overview and payment instructions' => 'Buyurtmani ko&#39;rib chiqish va to&#39;lov ko&#39;rsatmalaridan keyin','Before the order items section' => 'Buyurtma elementlari bo&#39;limidan oldin','Inside the order items section' => 'Buyurtma elementlari bo&#39;limi ichida','After the order items section' => 'Buyurtma elementlari bo&#39;limidan keyin','On the sidebar' => 'Yon panelda','Order downloads' => 'Yuklab olish uchun buyurtma','Gift message' => 'Sovg&#39;a xabari','Tools' => 'Asboblar','Troubleshooting' => 'Muammolarni bartaraf qilish; nosozliklarni TUZATISH','Debug options' => 'Nosozliklarni tuzatish imkoniyatlari','Debug mode' => 'Nosozliklarni tuzatish rejimi','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Nosozliklarni tuzatish rejimidan foydalanish veb-sayt ishiga ta&#39;sir qiladi. Ushbu parametrdan faqat muammolarni bartaraf etishda foydalaning.','Load unminified assets' => 'Minimallashtirilgan aktivlarni yuklang','Enhanced select fields' => 'Kengaytirilgan tanlash maydonlari','Fix automatic zoom-in on form fields' => 'Shakl maydonlarida avtomatik kattalashtirishni tuzating','Set <code>font-size</code> inside form fields to 16px' => 'Shakl maydonlari ichidagi <code>font-size</code> 16px qilib belgilang','Fluid Checkout' => 'Suyuqlikni tekshirish','Settings' => 'Sozlamalar','Support' => 'Qo&#39;llab-quvvatlash','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => 'Koʻproq imkoniyatlarni ochish uchun <a target="_blank" href="%s">PRO versiyasiga yangilang</a> .','(PRO)' => '(PRO)','(experimental)' => '(eksperimental)','Please verify your phone number.' => 'Iltimos, telefon raqamingizni tasdiqlang.','The Bluehost Plugin' => 'Bluehost plagini','Custom fields' => 'Maxsus maydonlar','Enable custom shipping email field' => 'Maxsus jo‘natma e-pochta maydonini yoqing','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Yoqilganda, Bluehost plaginidagi jo&#39;natma elektron pochta maydoni to&#39;lov shakliga qo&#39;shiladi.','Captcha Pro by BestWebSoft' => 'BestWebSoft tomonidan Captcha Pro','Captcha position' => 'Captcha pozitsiyasi','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Captcha qismini ko&#39;rsatish uchun joyni belgilang. Ba&#39;zi pozitsiyalar tanlangan captcha turiga qarab ishlamasligi mumkin.','Selecting a pickup point is required before proceeding.' => 'Davom etishdan oldin qabul qilish nuqtasini tanlash kerak.','Pickup point' => 'Qabul qilish punkti','Pickup point not selected yet.' => 'Qabul qilish nuqtasi hali tanlanmagan.','Pickup point:' => 'Qabul qilish nuqtasi:','Mailchimp for WooCommerce' => 'WooCommerce uchun Mailchimp','Subscribe checkbox' => 'Obuna bo&#39;lish katagiga belgi qo&#39;ying','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Hisob-kitob sahifasida obuna bo&#39;lish uchun belgini bekor qiling va uni har doim aloqa bosqichida ko&#39;rsating','Before Shipping Address' => 'Yuk tashishdan oldin manzil','(originally "%s")' => '(aslida &quot;%s&quot;)','After Shipping Address' => 'Yuk tashishdan keyin manzil','Selecting a collection point is required when shipping with FermoPoint.' => 'FermoPoint bilan jo&#39;natilayotganda yig&#39;ish nuqtasini tanlash talab qilinadi.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Belgilangan bo&#39;lsa, foydalanuvchilarga e-pochtadagi xatolar haqida xabar beradi. (Fluid Checkout funksiyani taklif qilgani uchun bu funksiya o‘chirib qo‘yilgan. Ushbu parametrga kiritilgan o‘zgartirishlar kuchga kirmaydi)','Enable Mail Check: (disabled feature)' => 'Pochta tekshiruvini yoqish: (o‘chirilgan xususiyat)','Carrier:' => 'Tashuvchi:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce elektron pochta marketingi','Sign up checkbox position' => 'Ro&#39;yxatdan o&#39;tish katakchasi pozitsiyasi','Move the sign up checkbox to the contact step' => 'Ro&#39;yxatdan o&#39;tish katakchasini kontakt bosqichiga o&#39;tkazing','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Yoqilganda, belgilash katakchasi Sendinblue plagin sozlamalarida belgilangan displey joylashuvidan qat&#39;i nazar, kontakt bosqichiga o&#39;tkaziladi.','Theme Betheme' => 'Betheme mavzusi','Checkout progress' => 'Hisob-kitob jarayoni','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Betheme-dan to&#39;lov bosqichlari bo&#39;limini to&#39;lov, savat va qabul qilingan buyurtma sahifalarida chiqaring.','Theme Fennik' => 'Mavzu Fennik','Breadcrumbs' => 'Non bo&#39;laklari','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Fluid Checkout sarlavhasi va altbilgisidan foydalanganda Fennik mavzusidagi non sindirish bo&#39;limini chiqaring.','Theme Go' => 'Mavzu Go','My account layout' => 'Mening hisobim tartibi','Enable wide layout on "My account" page.' => '&quot;Mening hisobim&quot; sahifasida keng tartibni yoqing.','Theme Impreza' => 'Impreza mavzusi','Header' => 'Sarlavha','Spacing for site header at the checkout page (in pixels)' => 'Hisob-kitob sahifasida sayt sarlavhasi uchun interval (piksellarda)','Only applicable when using the Impreza theme header at the checkout page.' => 'Faqat to&#39;lov sahifasida Impreza mavzusi sarlavhasidan foydalanilganda amal qiladi.','Theme Kapee' => 'Mavzu Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Qabul qilingan varaqlar, savat va buyurtma sahifalarida Kapee mavzusidan chiqish bosqichlari bo&#39;limini chiqaring.','Theme Porto' => 'Porto mavzusi','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'To&#39;lov, savat va qabul qilingan buyurtma sahifalarida Porto mavzusidan chiqish bosqichlari bo&#39;limini chiqaring.','Theme Pressmart' => 'Mavzu Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'To&#39;lov, savat va qabul qilingan buyurtma sahifalarida Pressmart mavzusidan chiqish bosqichlari bo&#39;limini chiqaring.','Theme The Gem' => 'Mavzu Gem','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Fluid Checkout sarlavhasi va altbilgisidan foydalanganda The Gem mavzusidagi to&#39;lov bosqichlari bo&#39;limini chiqaring.','Theme Woodmart' => 'Woodmart mavzusi','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Fluid Checkout sarlavhasi va altbilgisidan foydalanganda Woodmart mavzusidagi to&#39;lov bosqichlari bo&#39;limini chiqaring.','Checkout options' => 'Hisob-kitob opsiyalari','Disable the theme checkout options' => 'Mavzuni tekshirish parametrlarini o&#39;chiring','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Variantlar mahsulot tasviri, miqdor maydoni, oʻchirish tugmasi va mavzu boʻyicha qoʻshilgan mahsulot sahifasiga havolani koʻrsatish sukut boʻyicha oʻchirib qoʻyilgan.','Theme Atomion' => 'Mavzu Atomion','Order progress' => 'Buyurtmaning borishi','Display order progress from the theme' => 'Mavzu bo&#39;yicha buyurtma jarayonini ko&#39;rsatish','Display the form field labels visible on the page' => 'Sahifada ko&#39;rinadigan shakl maydoni teglarini ko&#39;rsating','It is recommended to keep this option enabled for a better user experience.' => 'Yaxshiroq foydalanuvchi tajribasi uchun ushbu parametrni yoqilgan holda saqlash tavsiya etiladi.','Theme ZK Nito' => 'Mavzu ZK Nito','Add extra fields to the checkout form' => 'To&#39;lov shakliga qo&#39;shimcha maydonlar qo&#39;shing','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Yuk tashish manzili bo&#39;limiga qo&#39;shimcha yuk e-pochtasi va yuk telefoni maydonini qo&#39;shadi.','Go to the home page' => 'Bosh sahifaga o&#39;ting','Skip to content' => 'Tarkibga oʻtish','Create an account' => 'Hisob ochish','Log in to your account' => 'Hisobingizga kiring','Already have an account?' => 'Hisobingiz bormi?','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s sifatida tizimga kirgan. <a href="%2$s">Chiqish</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Buyurtmangizning umumiy miqdori %s. Qo&#39;shimcha to&#39;lov talab qilinmaydi.','Close and continue with checkout' => 'Yoping va to&#39;lovni davom eting','Continue' => 'Davom eting','Parcel terminal' => 'Posilka terminali','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Ushbu vidjet Fluid Checkout bilan almashtirildi.</p><p> Fluid Checkout-dan foydalanganda, to&#39;g&#39;ri ishlashi uchun to&#39;lov sahifasi asl WooCommerce qisqa kodidan <code>[woocommerce_checkout]</code> foydalanishi kerak.</p><p> Qo&#39;shimcha ma&#39;lumot olish uchun Fluid Checkout hujjatlariga tashrif buyuring.</p>','Theme The7' => 'Mavzu 7','Additional header sections' => 'Qo&#39;shimcha sarlavha bo&#39;limlari','Output additional header sections if enabled in the theme settings.' => 'Mavzu sozlamalarida yoqilgan bo&#39;lsa, qo&#39;shimcha sarlavha bo&#39;limlarini chiqaring.','More information' => 'Batafsil ma&#39;lumot','Pick a Locker' => 'Shkafni tanlang','Page template' => 'Sahifa shabloni','Use `Order confirmation` page template for block-based themes' => 'Blokka asoslangan mavzular uchun “Buyurtmani tasdiqlash” sahifasi shablonidan foydalaning','Only applies when using a block-based theme.' => 'Faqat blokga asoslangan mavzudan foydalanilganda amal qiladi.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'To&#39;lov shakli','Apply styles to the Stripe payment form fields' => 'Stripe toʻlov formasi maydonlariga uslublarni qoʻllang','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Yoqilganda, Fluid Checkout plagin bilan moslik uchun optimallashtirilgan uslublarni qo&#39;llaydi. Agar siz Stripe toʻlov formasi maydonlari uchun maxsus uslublardan foydalanayotgan boʻlsangiz, buni oʻchirib qoʻyishingiz mumkin.','Theme Nyture' => 'Nyture mavzusi','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Fluid Checkout dan foydalanayotganda Nyture mavzusidagi to&#39;lov bosqichlari bo&#39;limini chiqaring.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Mijozlarga do&#39;kon administratori tomonidan qo&#39;lda yaratilgan yoki to&#39;lov vaqtida tugallanmagan buyurtmalar uchun to&#39;lovlarni amalga oshirish imkonini beradi.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Plagin WooCommerce Checkout Manager by Quadlayers Fluid Checkout bilan mos kelmaydi','Company name field for billing address' => 'Hisob-kitob manzili uchun kompaniya nomi maydoni','Change visibility for the company name field for the billing address section on the checkout form.' => 'To‘lov shaklidagi hisob-kitob manzili bo‘limi uchun kompaniya nomi maydonining ko‘rinishini o‘zgartiring.','Theme Bookshelf' => 'Mavzu kitob javoni','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Fluid Checkout-dan foydalanganda Bookshelf mavzusidan to&#39;lov bosqichlari bo&#39;limini chiqaring.','Account password' => 'Hisob paroli','An account will be created with the information provided at checkout when completing the order.' => 'Buyurtmani to&#39;ldirishda to&#39;lov vaqtida taqdim etilgan ma&#39;lumotlar bilan hisob yaratiladi.','Choose the style of the progress bar.' => 'Harakat paneli uslubini tanlang.','Bars' => 'Barlar','Theme Ireca' => 'Ireca mavzusi','WooCommerce page layout' => 'WooCommerce sahifa tartibi','Force wide layout on WooCommerce pages' => 'WooCommerce sahifalarida keng tartibni majburlash','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Bu WooCommerce sahifalarida kontent bo&#39;limi juda tor bo&#39;lmasligini ta&#39;minlaydi, shu jumladan to&#39;lov, savat, qabul qilingan buyurtma, buyurtma to&#39;lovi va hisob sahifalari.','WooCommerce Smart Coupons' => 'WooCommerce aqlli kuponlari','Position on checkout page' => 'To&#39;lov sahifasidagi pozitsiya','Choose where to display the available coupons section on the checkout page.' => 'To&#39;lov sahifasida mavjud kuponlar bo&#39;limi qaerda ko&#39;rsatilishini tanlang.','Before the progress bar' => 'Taraqqiyot satridan oldin','After the progress bar' => 'Taraqqiyot panelidan keyin','Before coupon codes section' => 'Kupon kodlari bo&#39;limidan oldin','Format phone numbers according to the rules for each country.' => 'Telefon raqamlarini har bir mamlakat uchun qoidalarga muvofiq formatlang.','Use precise phone number validation' => 'Telefon raqamini aniq tekshirishdan foydalaning','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Bu eksperimental xususiyat va barcha sozlamalarda kutilganidek ishlamasligi mumkin. Ehtiyotkorlik bilan foydalaning.','Phone number validation types used when precise validation is enabled.' => 'Telefon raqamini tekshirish turlari aniq tekshirish yoqilganda ishlatiladi.','Mobile' => 'Mobil','Fixed line' => 'Ruxsat etilgan chiziq','Toll free' => 'Bepul','Contact' => 'Aloqa','Multi step' => 'Ko&#39;p bosqichli','2 columns' => '2 ta ustun','1 column' => '1 ustun','Before checkout steps' => 'To&#39;lovdan oldingi bosqichlar','Or' => 'Yoki','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;1 ustunli&quot;</em> to&#39;lov sxemasidan foydalanganda, bu parametr har doim <em>&quot;To&#39;lovdan oldingi bosqichlar&quot;</em> ga o&#39;rnatiladi va ish stoli ko&#39;rinishiga ham tegishli.','Position for the extra order summary section on mobile.' => 'Mobil qurilmada qo&#39;shimcha buyurtmalar haqida qisqacha ma&#39;lumot bo&#39;limining pozitsiyasi.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;Sayt sarlavhasida&quot;</em> opsiyasi faqat chalg&#39;itmaydigan sarlavhadan foydalanilganda qo&#39;llaniladi.','On the site header (requires distraction-free header)' => 'Sayt sarlavhasida (chalg&#39;itmaydigan sarlavha talab qilinadi)','Initial state for the expansible order summary section on mobile.' => 'Mobil qurilmada kengaytiriladigan buyurtma xulosasi bo&#39;limining boshlang&#39;ich holati.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Normativ talablar tufayli uni quyidagi mamlakatlar uchun <em>kengaytirilgan</em> deb belgilashni tavsiya qilamiz: <strong>Germaniya</strong> , <strong>Avstriya</strong> , <strong>Shveytsariya</strong> , <strong>Niderlandiya</strong> , <strong>Polsha</strong> , <strong>Belgiya</strong> va <strong>Fransiya</strong> .','Collapsed' => 'Yig&#39;ilgan','Expanded' => 'Kengaytirilgan','Do not show' => 'Ko&#39;rsatilmasin','yes' => 'ha','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Agar to&#39;lov manzili bo&#39;limi yetkazib berish manzili bo&#39;limidan keyin ko&#39;rsatilsa va to&#39;lov telefoni maydoni &quot;majburiy&quot; deb belgilangan bo&#39;lsa, yetkazib berish telefoni maydoni &quot;majburiy&quot; deb belgilanishi mumkin. Bu parametr belgilanganda yetkazib berish manzili to&#39;lov manziliga ko&#39;chirilishi mumkinligini ta&#39;minlash uchun kerak, aks holda mijoz to&#39;lov shaklini to&#39;ldira olmasligi mumkin.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Agar toʻlov manzili boʻlimi yetkazib berish manzili boʻlimidan oldin koʻrsatilsa va yetkazib berish telefoni maydoni “majburiy” deb belgilangan boʻlsa, toʻlov telefoni maydoni “majburiy” deb belgilanishi mumkin. Bu parametr belgilanganda yetkazib berish manzili toʻlov manziliga koʻchirilishini taʼminlash uchun kerak, aks holda mijoz toʻlov shaklini toʻldira olmasligi mumkin.','Settings profiles' => 'Sozlamalar profillari','Settings profile' => 'Sozlamalar profili','You do not have permission to perform this action.' => 'Sizda bu amalni bajarish uchun ruxsat yo&#39;q.','You do not have permission to activate plugins.' => 'Sizda plaginlarni faollashtirish uchun ruxsat yo&#39;q.','Missing plugin.' => 'Plagin yo&#39;q.','Plugin activated.' => 'Plagin faollashtirildi.','The following changes will be applied:' => 'Quyidagi o&#39;zgarishlar qo&#39;llaniladi:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Fluid Checkout 5.0 versiyasidan beri sozlamalar boshqacha saqlanadi. Agar kerak bo&#39;lsa, oldingi versiyalarga o&#39;tishga imkon berish uchun eskirgan variantlar hali ham ma&#39;lumotlar bazasida saqlanadi.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Do&#39;koningiz yangi sozlamalarda taxminan 2 hafta davomida ishlayapti, shuning uchun siz ma&#39;lumotlar bazasida saqlangan eski parametrlarni tozalashingiz mumkin. Iltimos, tozalashdan so&#39;ng, agar siz plaginning oldingi versiyalariga o&#39;tishingiz kerak bo&#39;lsa, u barcha sozlamalar uchun standart qiymatlardan foydalanishini unutmang.','Fluid Checkout settings cleanup' => 'Suyuqlikni tekshirish sozlamalarini tozalash','Delete leftover options' => 'Qolgan variantlarni o&#39;chirish','Help us improve Fluid Checkout' => 'Suyuqlikni tekshirish xizmatini yaxshilashga yordam bering','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Anonim sayt muhiti hisobotlarini Fluid Checkout bilan baham ko&#39;ring, bu bizga tezroq yordam olish va moslikni yaxshilash hamda ta&#39;sirni o&#39;lchashga yordam beradi. Mijoz, foydalanuvchi yoki maxfiy ma&#39;lumotlar kiritilmagan. Siz istalgan vaqtda Asboblar sozlamalaridan nima ulashilishini tanlashingiz mumkin.','Enable site environment reports' => 'Sayt muhiti hisobotlarini yoqish','Review settings' => 'Sozlamalarni ko&#39;rib chiqish','This preview has expired. Reload the admin page to start a new preview.' => 'Ushbu oldindan ko&#39;rish muddati tugagan. Yangi oldindan ko&#39;rishni boshlash uchun administrator sahifasini qayta yuklang.','Preview expired' => 'Oldindan ko&#39;rish muddati tugadi','Orders cannot be placed in the preview.' => 'Buyurtmalarni oldindan ko&#39;rish rejimida joylashtirish mumkin emas.','Logging in is not available in the preview.' => 'Oldindan ko&#39;rish rejimida tizimga kirish imkoni yo&#39;q.','Accounts cannot be created in the preview.' => 'Oldindan ko&#39;rish rejimida hisoblarni yaratib bo&#39;lmaydi.','Requests to other sites are blocked in the preview.' => 'Boshqa saytlarga so&#39;rovlar oldindan ko&#39;rishda bloklangan.','Processing…' => 'Qayta ishlanmoqda…','Something went wrong. Please try again.' => 'Nimadir noto&#39;g&#39;ri ketdi. Iltimos, qaytadan urinib ko&#39;ring.','Activate plugin' => 'Plaginni faollashtiring','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - To&#39;liq to&#39;lov paketi','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Barcha PRO funksiyalari + barcha qo&#39;shimchalar, bitta narx. Shablonlarni loyihalash, optimallashtirilgan savat va buyurtma qabul qilingan sahifalar, hisoblarni moslashtirish va boshqa ko&#39;p narsalar.','Optimized order pay page' => 'Optimallashtirilgan buyurtma to&#39;lovi sahifasi','Express checkout buttons from supported payment methods' => 'Qo&#39;llab-quvvatlanadigan to&#39;lov usullaridan tezkor to&#39;lov tugmalari','Delayed account creation' => 'Hisob yaratish kechiktirildi','Address autocomplete with Google Maps APIs' => 'Google Xaritalar API&#39;lari bilan manzilni avtomatik to&#39;ldirish','Multiple saved addresses with the address book' => 'Manzillar kitobi bilan bir nechta saqlangan manzillar','EU-VAT assistant' => 'Yevropa Ittifoqi-QQS yordamchisi','Hide this section' => 'Bu bo&#39;limni yashirish','Learn more' => 'Batafsil ma&#39;lumot','Get early access' => 'Erta kirish huquqini oling','Activate add-on' => 'Qo&#39;shimchani faollashtirish','Get more out of your checkout journey' => 'Kassa safaringizdan ko&#39;proq foyda oling','Test API key' => 'API kalitini sinab ko&#39;ring','Guided setup' => 'Qo&#39;llanma asosida sozlash','Options' => 'Tanlovlar','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">Kassa opsiyalarida</a> tartib va dizaynni sozlang.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Mehmonlar uchun to&#39;lovni yoqish va/yoki <a href="%s">mijozlar hisoblari sozlamalarini</a> ko&#39;rib chiqish.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Optimallashtirilgan <a href="%1$s">savat</a> , <a href="%2$s">rahmat</a> va <a href="%3$s">buyurtma uchun to&#39;lov</a> sahifalarini yoqing.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Google Xaritalardan <a href="%s">manzilni avtomatik to&#39;ldirishni</a> yoqish.','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">Manzillar kitobi</a> bilan bir nechta saqlangan manzillarni yoqish.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Mavzu yoki o&#39;rnatgan boshqa plaginlar uchun biron bir <a href="%s">integratsiya variantlari</a> mavjudligini tekshiring.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Tezroq yordam oling va bizga moslikni yaxshilash va ta&#39;sirni o&#39;lchashda yordam bering. Asboblar sozlamalaridan <a href="%s">foydalanishni kuzatishni yoqing</a> .','Missing settings tab.' => 'Sozlamalar yorlig&#39;i yo&#39;q.','Getting started' => 'Ishni boshlash','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Ajoyib! To&#39;lov sahifangiz endi Fluid Checkout’da ishlayapti.</strong> Boshlash uchun bir nechta qadamlar:','Completed' => 'Tugallandi','Preview report data' => 'Hisobot ma&#39;lumotlarini oldindan ko&#39;rish','Send now' => 'Hozir yuboring','Auto-detect' => 'Avtomatik aniqlash','Afrikaans' => 'Afrikaans','Albanian' => 'Albancha','Amharic' => 'Amharcha','Arabic' => 'Arabcha','Armenian' => 'Armancha','Azerbaijani' => 'Ozarbayjon','Basque' => 'Baskcha','Belarusian' => 'Belaruscha','Bengali' => 'Bengal tili','Bosnian' => 'Bosniya','Bulgarian' => 'Bolgarcha','Burmese' => 'Birmacha','Catalan' => 'Katalancha','Chinese' => 'Xitoycha','Chinese (Simplified)' => 'Xitoycha (soddalashtirilgan)','Chinese (Hong Kong)' => 'Xitoy (Gonkong)','Chinese (Traditional)' => 'Xitoy (an&#39;anaviy)','Croatian' => 'Xorvatcha','Czech' => 'Chexcha','Danish' => 'Daniyacha','Dutch' => 'Gollandiyalik','English' => 'Inglizcha','English (Australian)' => 'Ingliz (Avstraliya)','English (Great Britain)' => 'Ingliz (Buyuk Britaniya)','Estonian' => 'Estoncha','Farsi' => 'Forscha','Finnish' => 'Fincha','Filipino' => 'Filippincha','French' => 'Fransuzcha','French (Canadian)' => 'Fransuz (Kanada)','Galician' => 'Galisiyalik','Georgian' => 'Gruzincha','German' => 'Nemischa','Greek' => 'Yunoncha','Gujarati' => 'Gujarati','Hebrew' => 'Ibroniycha','Hindi' => 'Hind tili','Hungarian' => 'Vengercha','Icelandic' => 'Islandcha','Indonesian' => 'Indonez tili','Italian' => 'Italiyacha','Japanese' => 'Yaponcha','Kannada' => 'Kannada','Kazakh' => 'Qozoqcha','Khmer' => 'Khmer','Korean' => 'Koreyscha','Kyrgyz' => 'Qirg&#39;iz','Lao' => 'Laoscha','Latvian' => 'Latviyacha','Lithuanian' => 'Litvacha','Macedonian' => 'Makedoniyalik','Malay' => 'Malaycha','Malayalam' => 'Malayalam','Marathi' => 'Marathi','Mongolian' => 'Mo&#39;g&#39;ulcha','Nepali' => 'Nepalcha','Norwegian' => 'Norvegcha','Polish' => 'Polsha','Portuguese' => 'Portugalcha','Portuguese (Brazil)' => 'Portugalcha (Braziliya)','Portuguese (Portugal)' => 'Portugalcha (Portugaliya)','Punjabi' => 'Panjobcha','Romanian' => 'Rumincha','Russian' => 'Ruscha','Serbian' => 'Serbcha','Sinhalese' => 'Sinhalcha','Slovak' => 'Slovakcha','Slovenian' => 'Slovencha','Spanish' => 'Ispancha','Spanish (Latin America)' => 'Ispan (Lotin Amerikasi)','Swahili' => 'Suaxili tili','Swedish' => 'Shvedcha','Tamil' => 'Tamilcha','Telugu' => 'Telugu','Thai' => 'Taylandcha','Turkish' => 'Turkcha','Ukrainian' => 'Ukraina','Urdu' => 'Urducha','Vietnamese' => 'Vetnamcha','Zulu' => 'Zulu','Google address autocomplete' => 'Google manzilini avtomatik to&#39;ldirish','Google Places API version' => 'Google Places API versiyasi','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Google Places API ning qaysi versiyasidan foydalanishni tanlang. Iloji boricha tezroq yangi Places API ga o&#39;tishni tavsiya qilamiz.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => '2025-yil 1-martdan boshlab &quot;Places API (Yangi)&quot; dan foydalanishni tavsiya qilamiz, Google &quot;Places API (Eski)&quot; versiyasini Eski holatga o&#39;tkazadi, ya&#39;ni siz endi ushbu xizmatni yangi API kalitlari uchun yoqolmaysiz va API ning ushbu versiyasi oxir-oqibat mavjud bo&#39;lmaydi. Eski API dan foydalanayotgan mavjud hisoblar uzilishlarsiz ishlashda davom etishi mumkin.','(Recommended)' => '(Tavsiya etiladi)','Google API key' => 'Google API kaliti','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Google API kalitingizni joylashtiring va uning ushbu veb-sayt uchun ishlashini tasdiqlash uchun sinov tugmasidan foydalaning. Kalitning haqiqiyligiga va domeningiz uchun ruxsat berilganligiga ishonch hosil qiling, aks holda manzil maydoni bloklanishi mumkin, bu esa mijozlarning buyurtmalarini bajarishiga to&#39;sqinlik qiladi.','Enable Google address autocomplete' => 'Google manzilini avtomatik to&#39;ldirishni yoqish','Enable address autocompletion using the Google Maps APIs.' => 'Google Xaritalar API&#39;lari yordamida manzilni avtomatik to&#39;ldirishni yoqing.','Google API language' => 'Google API tili','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Bu til Google Places API manzil takliflarini ko&#39;rsatish uchun ishlatiladi va manzillar ham ushbu tilda avtomatik ravishda to&#39;ldiriladi.','Result types' => 'Natija turlari','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Odatda yaxshiroq mos keladigan natijalarni beradigan har qanday turdagi natijalarni qabul qilish uchun bo&#39;sh qoldiring. <a href="%s" target="_blank">Batafsil ma&#39;lumot uchun hujjatlarga qarang</a> .<br> Manzilni avtomatik to&#39;ldirish maydonlarida qaytarish uchun 5 tagacha manzil qidiruv natijalarini tanlang.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">Qo&#39;llab-quvvatlanadigan turlari</a> haqida ko&#39;proq bilish uchun Google Xaritalar hujjatlariga tashrif buyuring.','Result types (Legacy API)' => 'Natija turlari (Eski API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Places API (Legacy) dan foydalanganda qaysi turdagi manzil qidiruv natijalarini qaytarish kerak.<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">Qo&#39;llab-quvvatlanadigan turlar</a> haqida ko&#39;proq bilish uchun Legacy Google Places API hujjatlariga tashrif buyuring.','Company fields' => 'Kompaniya maydonlari','Enable autocomplete for the company name if available' => 'Agar mavjud bo&#39;lsa, kompaniya nomi uchun avtomatik to&#39;ldirishni yoqing','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Google Xaritalar API&#39;laridan qaytarilganda, kompaniya nomi ma&#39;lumotlari bilan kompaniya maydonini avtomatik to&#39;ldirishni yoqish.','Business search' => 'Biznes qidiruvi','Enable search for businesses in the company field' => 'Kompaniya sohasida bizneslarni qidirishni yoqish','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Kompaniya maydoniga yozayotganda biznes bilan bog&#39;liq manzillarni taklif qilishni yoqing, keyin takliflardan biznes tanlanganda barcha manzil maydonlarini avtomatik ravishda to&#39;ldiring.','Company result types' => 'Kompaniya natijalarining turlari','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Avtomatik to&#39;ldirish kompaniyasi maydonlarida ko&#39;rsatish uchun 5 tagacha manzil qidiruv natijalarini tanlang.<br> Tavsiya etilgan qiymat - bu ko&#39;pgina biznes turlarini o&#39;z ichiga olgan <code>establishment</code> .<br> Biznesga aloqador bo&#39;lmagan natijalarni ham qo&#39;shib hisoblaganda, har qanday turdagi natijalarni qabul qilish uchun maydonni bo&#39;sh qoldiring.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">Qo&#39;llab-quvvatlanadigan turlari</a> haqida ko&#39;proq bilish uchun Google Xaritalar hujjatlariga tashrif buyuring.','Google logo' => 'Google logotipi','Show text and logo "Powered by Google"' => '&quot;Google tomonidan ishlab chiqilgan&quot; matni va logotipini ko&#39;rsatish','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Belgilanganida, manzilni avtomatik to&#39;ldirish takliflari oynasining pastki qismida &quot;Google tomonidan ishlab chiqilgan&quot; matni va logotipi ko&#39;rsatiladi.','Brasil API address autocomplete' => 'Brasil API manzilini avtomatik to&#39;ldirish','Brasil API' => 'Braziliya APIsi','Enable Brasil API address autocomplete for CEP fields' => 'CEP maydonlari uchun Brasil API manzilini avtomatik to&#39;ldirishni yoqish','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'CEP/Pochta indeksi maydonidan foydalanib manzillarni olish va avtomatik to&#39;ldirish uchun Brasil API dan foydalaning. Faqat Braziliya manzillari uchun tegishli.','API version' => 'API versiyasi','Choose which version of the Brasil API CEP method to use.' => 'Brasil API CEP usulining qaysi versiyasidan foydalanishni tanlang.','Address book migration' => 'Manzil kitobi migratsiyasi','WooCommerce addresses' => 'WooCommerce manzillari','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'WooCommerce’dan mavjud yetkazib berish va to‘lov manzillarini mijozlarning manzillar kitobiga nusxalash.','Enable the address book feature' => 'Manzillar kitobi funksiyasini yoqish','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Mijozlarga bir nechta manzillarni saqlashga va yetkazib berish va hisob-kitob qilish uchun ishlatiladigan standart manzilni belgilashga ruxsat bering.','Address labels' => 'Manzil yorliqlari','Allow customers to add a custom label for each address' => 'Mijozlarga har bir manzil uchun maxsus yorliq qo&#39;shishga ruxsat bering','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Manzil yorliqlari mijozlarga saqlangan manzillarini (masalan: &quot;Onamning uyi&quot;) farqlashni osonlashtiradi. Manzil yorliqlari mijozlar uchun shaxsiy bo&#39;lib, buyurtma tafsilotlari sahifasida yoki schyot-fakturalarda ko&#39;rsatilmaydi yoki chop etilmaydi.','Display layout' => 'Displey tartibi','Choose how saved addresses are displayed at checkout and on the cart.' => 'Saqlangan manzillar to&#39;lov vaqtida va savatda qanday ko&#39;rsatilishini tanlang.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'To&#39;lov vaqtida va savatda amal qiladi. Hisob sahifasida saqlangan manzillar har doim kartalar tartibidan foydalanadi.','Address cards' => 'Manzil kartalari','Address list' => 'Manzillar ro&#39;yxati','Dropdown field' => 'Ochiluvchi maydon','Address search' => 'Manzil qidiruvi','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Mijoz kamida shuncha saqlangan manzillarga ega bo&#39;lganda, frontendda manzil qidiruv filtrini ko&#39;rsatish.','Not used when display layout is set to dropdown field.' => 'Displey tartibi ochiladigan maydonga o&#39;rnatilganda ishlatilmaydi.','Addresses' => 'Manzillar','Enable cart page optimizations to see more options' => 'Ko&#39;proq variantlarni ko&#39;rish uchun savat sahifasini optimallashtirishni yoqing','Sticky order summary' => 'Yopishqoq buyurtma xulosasi','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Savat sahifasida kupon kodlari bo&#39;limini ko&#39;rsatish uchun joyni tanlang. Faqat AJAX savati yoqilgan bo&#39;lsa va WooCommerce sozlamalarida kupon kodlaridan foydalanish yoqilgan bo&#39;lsa amal qiladi.','Layout of cross-sell' => 'Kross-sotuv sxemasi','Cross-sells displayed' => 'Ko&#39;rsatilgan o&#39;zaro savdolar','Items' => 'Elementlar','Cart page optimization' => 'Savat sahifasini optimallashtirish','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Savatingizga to&#39;lovingizdagi kabi aniq, konversiyaga yo&#39;naltirilgan tartibni bering.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Izchil xarid qilish jarayoni uchun savatcha tartibini to&#39;lov sahifasiga moslang.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Savatni doimo fonda yangilab turing, miqdorlar o&#39;zgarganda to&#39;liq sahifa qayta yuklanmaydi.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Kupon kodlarini, yetkazib berishni va o&#39;zaro savdolarni eng yaxshi konvertatsiya qilinadigan joylarga joylashtiring.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Buyurtma xulosasini aylantirish paytida ko&#39;rinadigan qilib qo&#39;ying va xaridorlar ishonchga muhtoj bo&#39;lgan joylarda ishonch belgilarini qo&#39;shing.','Columns' => 'Ustunlar','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'To&#39;lov bosqichlari, buyurtma xulosasi va boshqa bo&#39;limlar uchun umumiy uslublar. Boshqa to&#39;lov, savat, rahmat (buyurtma qabul qilindi) va buyurtma sahifalarini ko&#39;rish uchun amal qiladi.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => '<em>&quot;Ajratish&quot;</em> dizayn shabloni bilan <em>&quot;1 ustun&quot;</em> maketidan foydalanilganda, o&#39;ng ustun faqat sahifa yon paneli vidjeti maydoni faol bo&#39;lganda ko&#39;rsatiladi (Cheklov Yon paneli, Savat yon paneli yoki Qabul qilingan buyurtma yon paneli). Aks holda, sahifa Ajratish uslublari bilan bitta ustun sifatida qoladi.','Split column background' => 'Ustun fonini ajratish','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => '&quot;Bo&#39;lingan dizayn&quot; ikkilamchi ustuni uchun fon rangini tanlang. Buyurtma xulosasi fon rangidan foydalanish uchun bo&#39;sh qoldiring.','Page templates' => 'Sahifa shablonlari','Checkout template' => 'To&#39;lov shabloni','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Kassada chalg&#39;itadigan narsalar kamroq bo&#39;lishi uchun tavsiya etiladi. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Savatdan voz kechish haqidagi tadqiqotni o&#39;qing</a> .','Sticky progress bar' => 'Yopishqoq progress paneli','Progress bar style' => 'Jarayon paneli uslubi','Order totals' => 'Buyurtmalarning umumiy summasi','Background color' => 'Fon rangi','Action link' => 'Harakat havolasi','Mobile order summary' => 'Mobil buyurtma xulosasi','Mobile initial state' => 'Mobil boshlang&#39;ich holat','Enable editing cart items at checkout' => 'To&#39;lov vaqtida savatdagi elementlarni tahrirlashni yoqish','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Mijozlarga mahsulot miqdorini o&#39;zgartirish yoki to&#39;g&#39;ridan-to&#39;g&#39;ri to&#39;lov sahifasida mahsulotlarni olib tashlashga ruxsat bering.','Cart item errors' => 'Savat elementidagi xatolar','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Faqat kupon kodi to&#39;lov yoki savat sahifalarida alohida bo&#39;lim sifatida ko&#39;rsatilganda va WooCommerce sozlamalarida kupon kodlaridan foydalanish yoqilgan bo&#39;lsa amal qiladi.','Coupon codes position' => 'Kupon kodlari pozitsiyasi','Apply coupon button' => 'Kuponni qo&#39;llash tugmasi','Select style of the "apply coupon" button.' => '&quot;Kuponni qo&#39;llash&quot; tugmachasining uslubini tanlang.','Address line 2' => 'Manzil qatori 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Ushbu sozlama &quot;To&#39;lov&quot; va &quot;Mahalliy olib ketish&quot; bo&#39;limlari o&#39;rtasida taqsimlanadi. Mahalliy olib ketish bo&#39;limida, shuningdek, &quot;Yetkazib berish/Olib ketish&quot; ni tanlash vositasi yetkazib berish usuli bo&#39;limida (manzildan oldin) yoki alohida bo&#39;lim sifatida (keyin) ko&#39;rsatilishini ham belgilaydi.','Customer accounts' => 'Mijozlar hisoblari','Guest checkout' => 'Mehmonlar uchun kassa','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'WooCommerce hisob sozlamalari sahifasidan mehmon sifatida ro&#39;yxatdan o&#39;tish, tizimga kirish va hisob yaratish imkoniyatlari. Ular sizning qulayligingiz uchun bu yerda boshqariladi va shuning uchun siz har bir sozlamalar profili uchun turli qiymatlardan foydalanishingiz mumkin.','Allow customers to checkout without an account' => 'Mijozlarga hisob qaydnomasisiz to&#39;lovlarni amalga oshirishga ruxsat bering','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'Mijozlardan to&#39;lov vaqtida hisob yaratish yoki tizimga kirish so&#39;ralmasligi uchun <strong>tavsiya etiladi</strong> , bu esa konversiya stavkalarini pasaytirishi mumkin.','When disabled, customers must log in or create an account to complete the purchase.' => 'O&#39;chirilgan bo&#39;lsa, mijozlar xaridni yakunlash uchun tizimga kirishlari yoki hisob yaratishlari kerak.','Login at checkout' => 'To&#39;lov vaqtida tizimga kiring','Enable log-in during checkout' => 'To&#39;lov vaqtida tizimga kirishni yoqing','Show a link for returning customers to log in from the checkout page.' => 'Qaytib kelayotgan mijozlar uchun to&#39;lov sahifasidan tizimga kirish uchun havolani ko&#39;rsating.','Account creation' => 'Hisob yaratish','Allow customers to create an account during checkout' => 'Mijozlarga to&#39;lov vaqtida hisob yaratishga ruxsat bering','Customers can create an account before placing their order.' => 'Mijozlar buyurtma berishdan oldin hisob yaratishlari mumkin.','Allow customers to create an account from the My account page' => 'Mijozlarga Mening hisobim sahifasidan hisob yaratishga ruxsat bering','Customers can register a new account from the My account page.' => 'Mijozlar &quot;Mening hisobim&quot; sahifasidan yangi hisob qaydnomasini ro&#39;yxatdan o&#39;tkazishlari mumkin.','Username' => 'Foydalanuvchi nomi','Generate from customer\'s name' => 'Mijoz nomidan yarating','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'Mijozlardan to&#39;lov vaqtida foydalanuvchi nomini tanlash so&#39;ralmasligi uchun <strong>tavsiya etiladi</strong> , bu esa konversiya stavkalarini pasaytirishi mumkin.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Foydalanuvchi nomi mijoz nomidan yoki nomdan foydalanib bo&#39;lmaganda elektron pochta manzilidan yaratiladi.','Password' => 'Parol','Send password setup link' => 'Parolni o&#39;rnatish havolasini yuboring','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => 'Mijozlardan to&#39;lov vaqtida parol o&#39;rnatish so&#39;ralmasligi uchun <strong>tavsiya etiladi</strong> , bu esa konversiya stavkalarini pasaytirishi mumkin.','Customers receive an email to create their password securely.' => 'Mijozlar parollarini xavfsiz yaratish uchun elektron pochta xabarlarini olishadi.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Ro&#39;yxatdan o&#39;tgan mijozlarga tizimga kirmasdan to&#39;lovni yakunlash imkonini bering va aloqa ma&#39;lumotlari mos kelganda buyurtmani mavjud hisoblari bilan bog&#39;lang.','Existing account message' => 'Mavjud hisob xabari','Let customers create an account after placing their order, from the thank you page.' => 'Mijozlarga buyurtma bergandan so&#39;ng, minnatdorchilik sahifasidan hisob yaratishga ruxsat bering.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Ushbu bo&#39;limdagi imkoniyatlar mehmonlar uchun to&#39;lov va hisoblarni moslashtirish yoqilgan bo&#39;lsa mavjud bo&#39;ladi. Kechiktirilgan hisob yaratishni sozlash uchun yuqoridagi ikkala funksiyani ham yoqing.','Enable delayed account creation' => 'Kechiktirilgan hisob yaratishni yoqish','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Mehmonning hisob-kitob qilish va hisoblarni moslashtirish funksiyalari yoqilganda, kechiktirilgan hisob yaratish funksiyasini yoqish.','Section position' => 'Bo&#39;lim pozitsiyasi','Before customer details section' => 'Mijoz ma&#39;lumotlari bo&#39;limidan oldin','After customer details section' => 'Mijoz ma&#39;lumotlaridan keyingi bo&#39;lim','Account creation benefits' => 'Hisob yaratish afzalliklari','Leaving the field empty will display the default text.' => 'Maydonni bo&#39;sh qoldirsangiz, standart matn ko&#39;rsatiladi.','Inline buttons' => 'Ichki tugmalar','Required fields' => 'Majburiy maydonlar','Enable gift message fields at checkout' => 'To&#39;lov vaqtida sovg&#39;a xabarlari maydonlarini yoqing','Expanded gift message' => 'Kengaytirilgan sovg&#39;a xabari','Display gift message field always expanded' => 'Sovg&#39;a xabari maydonini ko&#39;rsatish har doim kengaytirilgan','Gift message in order details' => 'Buyurtma tafsilotlari bo&#39;yicha sovg&#39;a xabari','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Hozirda ushbu bo&#39;limda integratsiyalar mavjud emas. Har bir plagin va mavzuga tegishli parametrlar faqat o&#39;sha plagin yoki mavzu faollashtirilganda paydo bo&#39;ladi.','Phone fields' => 'Telefon maydonchalari','Field visibility' => 'Maydon ko&#39;rinishi','Field position' => 'Maydon pozitsiyasi','Phone country code & validation' => 'Telefon mamlakat kodi va tasdiqlash','Country' => 'Mamlakat','Enable country on phone fields' => 'Telefon maydonlarida mamlakatni yoqish','Filter countries for shipping or billing' => 'Yetkazib berish yoki to&#39;lov uchun mamlakatlarni filtrlang','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Har bir telefon maydonidagi mamlakat tanlagichini do&#39;koningizda yetkazib berish yoki to&#39;lov uchun ruxsat berilgan mamlakatlar bilan cheklang.','Validation' => 'Tasdiqlash','Enable simple validation based on country rules' => 'Mamlakat qoidalariga asoslangan oddiy tasdiqlashni yoqish','Checks that the phone number is valid for the selected country, including country code and length.' => 'Telefon raqami tanlangan mamlakat uchun amal qilishini, jumladan, mamlakat kodi va uzunligini tekshiradi.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Tanlangan mamlakat uchun raqamning amaldagi mobil, statsionar yoki boshqa qabul qilingan turi ekanligini qat&#39;iyroq tekshiring. Ba&#39;zi amaldagi raqamlar rad etilishi mumkin.','Validation types' => 'Tasdiqlash turlari','Placeholders' => 'O&#39;rin egalari','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Hozirda boshqarish uchun litsenziya kalitlari yo&#39;q. Litsenziyalangan Fluid Checkout plagini yoki qo&#39;shimchasi faol bo&#39;lganda litsenziya kalitlari bu yerda ko&#39;rsatiladi.','Default delivery type' => 'Standart yetkazib berish turi','Choose which delivery type will be selected by default.' => 'Sukut bo&#39;yicha qaysi yetkazib berish turi tanlanishini tanlang.','Shipping zone fields' => 'Yuk tashish zonasi maydonlari','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Mahalliy olib ketish yetkazib berish zonasi filtri maydonlari uchun qaysi maydonlar ko&#39;rsatilishini tanlang. Barcha mavjud variantlarni ko&#39;rsatish uchun bo&#39;sh qoldiring.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Bu maydonlar mahalliy yetkazib berish usullari uchun filtr sifatida ko&#39;rsatiladi. Agar mos keladigan plaginlar to&#39;g&#39;ri ishlashi uchun ularni talab qilsa, ba&#39;zi maydonlar bu yerda tanlanmagan bo&#39;lsa ham, to&#39;lov vaqtida paydo bo&#39;lishi mumkin.','Order shipping address' => 'Buyurtma yetkazib berish manzili','Order pay page optimization' => 'Buyurtma to&#39;lovi sahifasini optimallashtirish','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'To&#39;lanmagan buyurtmalarga to&#39;lov bilan bir xil aniq, konversiyaga yo&#39;naltirilgan tartibni bering.','Optimize the layout of the order pay page for orders pending payment.' => 'To&#39;lovni kutayotgan buyurtmalar uchun buyurtma to&#39;lovi sahifasining tartibini optimallashtiring.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Izchil xarid qilish jarayoni uchun buyurtma to&#39;lovi tajribasini kassangizdagi holatga moslashtiring.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Xaridorlar to&#39;lovni amalga oshirishdan oldin ishonch bildirishlari kerak bo&#39;lgan joylarda ishonch belgilari va nishonlarini qo&#39;shing.','Thank you page optimization' => 'Sahifani optimallashtirish uchun rahmat','Make the thank you page and order details clearer for customers after they buy.' => 'Xaridorlar sotib olgandan keyin minnatdorchilik sahifasi va buyurtma tafsilotlarini tushunarli qiling.','Optimize the thank you page and account order details with a clearer layout.' => 'Minnatdorchilik sahifasi va hisob buyurtmasi tafsilotlarini aniqroq tartib bilan optimallashtiring.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Buyurtma holatining borishi, amallar, yuklab olishlar va eslatmalarni ular mantiqiy bo&#39;lgan joylarda ko&#39;rsating.','Customize order details sections on email notifications.' => 'Elektron pochta bildirishnomalarida buyurtma tafsilotlari bo&#39;limlarini sozlang.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Xaridorlar sotib olgandan keyin ishonchga muhtoj bo&#39;lgan joylarda ishonch belgilari va nishonlarini qo&#39;shing.','Email notifications' => 'Elektron pochta orqali bildirishnomalar','Enable thank you page and order details optimizations to see more options' => 'Ko&#39;proq variantlarni ko&#39;rish uchun minnatdorchilik sahifasi va buyurtma tafsilotlarini optimallashtirishni yoqing','Use wide layout on thank you page' => 'Rahmat sahifasida keng maketdan foydalaning','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Ushbu parametrlar minnatdorchilik sahifasiga, hisob sahifalarida va elektron pochta xabarnomalarida buyurtma tafsilotlarini ko&#39;rishga ta&#39;sir qiladi.','Save settings' => 'Sozlamalarni saqlash','Docs' => 'Hujjatlar','Cart' => 'Savat','Thank you' => 'rahmat','Address autocomplete' => 'Manzilni avtomatik to&#39;ldirish','Trust badges' => 'Ishonch nishonlari','You do not have permission to save these settings.' => 'Sizda ushbu sozlamalarni saqlash uchun ruxsat yo&#39;q.','Invalid save request.' => 'Saqlash so&#39;rovi noto&#39;g&#39;ri.','Your settings have been saved.' => 'Sozlamalaringiz saqlandi.','Saving...' => 'Saqlanmoqda...','Settings could not be saved. Please try again.' => 'Sozlamalarni saqlab bo&#39;lmadi. Qaytadan urinib ko&#39;ring.','Dismiss notice' => 'Bildirishnomani rad etish','Open settings menu' => 'Sozlamalar menyusini ochish','Close settings menu' => 'Sozlamalar menyusini yopish','Preview' => 'Oldindan ko&#39;rish','Expand preview' => 'Oldindan ko&#39;rishni kengaytirish','Collapse preview' => 'Oldindan ko&#39;rishni yopish','Show header and footer' => 'Sarlavha va altbilgilarni ko&#39;rsatish','Hide header and footer' => 'Sarlavha va altbilgilarni yashirish','Page preview' => 'Sahifani oldindan ko&#39;rish','Preview viewport' => 'Ko&#39;rish maydonini oldindan ko&#39;rish','Tablet' => 'Planshet','Desktop' => 'Ish stoli','Preview width' => 'Oldindan ko&#39;rish kengligi','Decrease width' => 'Kenglikni kamaytirish','Preview width in pixels' => 'Piksellarda oldindan ko&#39;rish kengligi','Increase width' => 'Kenglikni oshiring','Preview as' => 'Oldindan ko&#39;rish','Guest' => 'Mehmon','Logged in' => 'Kirish','Preview page' => 'Oldindan ko&#39;rish sahifasi','Expand preview for a closer look' => 'Batafsilroq ko&#39;rish uchun oldindan ko&#39;rishni kengaytirish','Available with %s.' => '%s bilan mavjud.','Turn them on' => 'Ularni yoqing','Optimizations for this page are turned off. %s to preview the page.' => 'Bu sahifa uchun optimallashtirish o&#39;chirilgan. Sahifani oldindan ko&#39;rish uchun %s bosing.','%s preview' => '%s oldindan ko&#39;rish','Isolated session · nothing is saved' => 'Izolyatsiya qilingan sessiya · hech narsa saqlanmadi','Usage tracking' => 'Foydalanishni kuzatish','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Fluid Checkout mosligini yaxshilashga yordam berish uchun sayt muhitiga oid sezgir bo&#39;lmagan hisobotlarni yuboring. Quyidagi sozlamalarda yoqilmaguncha hisobotlar yuborilmaydi.','Send usage tracking reports to Fluid Checkout' => 'Foydalanishni kuzatish hisobotlarini Fluid Checkout’ga yuboring','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Ushbu hisobotlar bizga saytingiz uchun moslik va qo&#39;llab-quvvatlashni yaxshilashga yordam beradi va yoqilganda haftalik ravishda yuboriladi.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Hisobotlarga mijoz, administrator foydalanuvchisi yoki boshqa biron bir maxfiy ma&#39;lumot kiritilmagan.','Basic environment info' => 'Asosiy atrof-muhit haqida ma&#39;lumot','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'WordPress, PHP, WooCommerce, mavzular va plaginlar ro&#39;yxati ma&#39;lumotlari. Hisobot yoqilganda har doim qo&#39;shiladi. Saytingiz qanday muhitda ishlayotganini tushunishimizga yordam beradi.','Plugin settings' => 'Plagin sozlamalari','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Qoʻllab-quvvatlash soʻrovlari boʻyicha yordam berish uchun Fluid Checkout plagini sozlamalarini yuboradi va plaginlarimizdan qanday foydalanayotganingizni tushunishimizga yordam beradi.','Coming soon' => 'Tez kunlarda','Sales metrics' => 'Savdo ko&#39;rsatkichlari','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Fluid Checkout’ni o‘rnatishdan oldingi bir yil davomida bugungi kungacha bo‘lgan oylik buyurtmalar soni va umumiy savdolar. O‘rnatilgan plaginlarimiz bilan ko‘proq pul ishlayotganingizni tushunishimizga yordam beradi. Mijoz yoki foydalanuvchi ma’lumotlari hech qachon yuborilmaydi.','Utilities' => 'Kommunal xizmatlar','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => '<code>select2</code> o&#39;rniga <code>TomSelect</code> ochiladigan komponentlaridan foydalaning','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect - bu Select2 ga qaraganda xatolarga kamroq moyil bo&#39;lgan sodda ochiladigan tanlov komponenti, ammo bir xil funksiyalarni taklif qiladi.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Kichik qurilmalarda forma maydonlari bilan o&#39;zaro aloqada avtomatik ravishda kattalashtirishning oldini olish uchun ushbu plagin tomonidan optimallashtirilgan sahifalarda forma maydonlari ichidagi shrift o&#39;lchamini 16 pikselga o&#39;rnatadi.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Shrift o&#39;lchami 16 pikseldan kichikroq bo&#39;lganda, Safari va boshqa brauzerlar matnni o&#39;qishni osonlashtirish uchun mobil qurilmalarda avtomatik ravishda kattalashtirishi mumkin.','Enable script processing tracking on the browser console.' => 'Brauzer konsolida skriptni qayta ishlashni kuzatishni yoqish.','Unminified assets' => 'Minimallashtirilmagan aktivlar','Google Maps scripts' => 'Google Xaritalar skriptlari','Do not remove duplicate Google Maps scripts' => 'Google Xaritalarining takroriy skriptlarini olib tashlamang','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Yoqilganda, takroriy Google Xaritalar skriptlari O&#39;CHIRILMAYDI, bu esa xatolar va ishlash muammolariga olib kelishi mumkin. Ushbu parametrdan faqat muammolarni bartaraf etishda foydalaning.','Widget areas' => 'Vidjet hududlari','Last step on mobile' => 'Mobil qurilmada oxirgi qadam','Display widgets only at last step on mobile' => 'Vidjetlarni faqat mobil qurilmada oxirgi bosqichda ko&#39;rsatish','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Mobil qurilmalarda oxirgi to&#39;lov bosqichini ko&#39;rayotganda faqat to&#39;lov ishonch nishoni vidjetlarini ko&#39;rsatish','Standard' => 'Standart','VAT number field' => 'QQS raqami maydoni','Add a VAT number field to the billing form.' => 'Hisob-kitob shakliga QQS raqami maydonini qo&#39;shing.','Field label' => 'Maydon yorlig&#39;i','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'QQS raqami maydonining yorlig&#39;ini o&#39;rnating (ya&#39;ni, QQS raqami). Ko&#39;p tilli veb-saytlarda bu maydonni bo&#39;sh qoldirib, asl satrni tarjima qilish yaxshiroqdir.','VAT Number' => 'QQS raqami','EU-VAT' => 'Yevropa Ittifoqi-QQS','Enable the VAT number field to see more options' => 'Ko&#39;proq variantlarni ko&#39;rish uchun QQS raqami maydonini yoqing','VAT validation' => 'QQSni tasdiqlash','Validate VAT number field for EU-VAT during checkout' => 'To&#39;lov vaqtida Yevropa Ittifoqi QQS raqami maydonini tasdiqlang','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Taqdim etilgan QQS raqami Yevropa VIES ma&#39;lumotlar bazasida (QQS ma&#39;lumotlar almashinuvi tizimi) ro&#39;yxatdan o&#39;tgan haqiqiy QQS raqami ekanligini tekshiradi.','Shop VAT number' => 'QQS raqami','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Do&#39;konning QQS raqami EU-QQS tasdiqlashini so&#39;rash uchun ishlatilgan va schyot-fakturalarda bosilgan.<br> <strong>Do&#39;koningizning QQS raqamingizni qo&#39;shishingizni qat&#39;iy tavsiya qilamiz</strong> , aks holda VIES maslahat natijalari buxgalteriya maqsadlari uchun haqiqiy bo&#39;lmasligi mumkin.<br> Ya&#39;ni: <code>ATU99999999</code> yoki <code>EE999999999</code> .','Reverse charge' => 'Teskari zaryadlash','Apply reverse charge mechanism' => 'Teskari zaryadlash mexanizmini qo&#39;llang','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Mijozning QQS raqami haqiqiy bo&#39;lganda, soliq stavkasini nolga o&#39;rnating va hisob-fakturalarda &quot;Teskari to&#39;lov&quot; ni ko&#39;rsating. Do&#39;kon joylashgan mamlakatga qarab, boshqa &quot;Teskari to&#39;lov&quot; matni talab qilinishi mumkin.','Same country' => 'Xuddi shu mamlakat','Apply reverse charge mechanism for transactions in the shop country:' => 'Do&#39;kon mamlakatidagi tranzaksiyalar uchun teskari to&#39;lov mexanizmini qo&#39;llang:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Do&#39;kon joylashgan mamlakatdagi kompaniyalar o&#39;rtasidagi tranzaksiyalar uchun teskari to&#39;lov mexanizmini qo&#39;llash imkonini beradi.','Reverse charge exceptions' => 'Teskari to&#39;lov istisnolari','Select additional countries to skip applying the reverse charge mechanism.' => 'Teskari to&#39;lov mexanizmini qo&#39;llashni o&#39;tkazib yuborish uchun qo&#39;shimcha mamlakatlarni tanlang.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Ushbu mamlakatlardan kelgan buyurtmalarga, hatto amaldagi QQS raqami taqdim etilgan taqdirda ham, soliqlar undiriladi.','Reverse charge label on invoices' => 'Hisob-fakturalardagi teskari to&#39;lov yorlig&#39;i','Set the label of "reverse charge" on the checkout page and order details.' => 'To&#39;lov sahifasida va buyurtma tafsilotlarida &quot;teskari to&#39;lov&quot; yorlig&#39;ini o&#39;rnating.','Reverse charge text on invoices' => 'Hisob-fakturalardagi teskari to&#39;lov matni','Set the label of "reverse charge" text on invoices.' => 'Hisob-fakturalarga &quot;teskari to&#39;lov&quot; matni yorlig&#39;ini o&#39;rnating.','Tax to be paid on reverse charge basis' => 'Teskari to&#39;lov asosida to&#39;lanadigan soliq','Company name' => 'Shirkat nomi','Autocomplete company name from VAT number' => 'QQS raqamidan kompaniya nomini avtomatik ravishda to&#39;ldirish','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Mijoz tomonidan taqdim etilgan amaldagi QQS raqami asosida hisob-kitob kompaniyasi nomini to&#39;ldiring.','Company name editing' => 'Kompaniya nomini tahrirlash','Allow editing of auto-filled company name' => 'Avtomatik to&#39;ldirilgan kompaniya nomini tahrirlashga ruxsat berish','When enabled, customers can change the company name associated with the provided VAT number.' => 'Yoqilganda, mijozlar taqdim etilgan QQS raqami bilan bog&#39;liq kompaniya nomini o&#39;zgartirishlari mumkin.','EU-VAT for digital goods' => 'Raqamli tovarlar uchun Yevropa Ittifoqi QQS','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => '2015-yil 1-yanvardan boshlab raqamli tovarlarga oid Yevropa Ittifoqining QQS qoidalariga faqat B2C tranzaksiyalariga ta&#39;sir qiluvchi o&#39;zgartirishlar kiritildi. Raqamli tovarlarga QQS mijozning joylashuvi asosida hisoblanishi kerak va buning dalillari (IP-manzil va to&#39;lov manzili) to&#39;planishi kerak.','Tax classes for digital goods' => 'Raqamli tovarlar uchun soliq sinflari','Select some tax classes' => 'Ba&#39;zi soliq sinflarini tanlang','Location evidence' => 'Joylashuv dalillari','Collect customer\'s location evidence' => 'Mijozning joylashuvi haqidagi dalillarni to&#39;plang','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'IP-manzilni saqlaydi va uni mijozning toʻlov manzili bilan taqqoslaydi. Agar mijozning toʻlov manzilidagi mamlakat va IP-manzil mos kelmasa, mijoz toʻlov sahifasidagi katakchani belgilash orqali oʻzining toʻlov manzilini tasdiqlashi kerak.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Bu parametr Fluid Checkout’da boshqariladi. <a href="%s">Uni Mijozlar hisoblari sozlamalarida o‘zgartiring</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Bu parametr Fluid Checkout’da boshqariladi. Uni Fluid Checkout &gt; Mijozlar hisoblari ostida oʻzgartiring.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Bu parametr Fluid Checkout’da boshqariladi. Fluid Checkout yoqilganda, yetkazib berish manzili har doim “Mijozning yetkazib berish manzili uchun standart” ga o‘rnatiladi. Mijozlar to‘lov vaqtida turli yetkazib berish va to‘lov manzillarini taqdim etishlari mumkin.<br><br> Standart to&#39;lov manzilini yetkazib berish manzili bilan bir xil qilib belgilash imkoniyati <a href="%s">Fluid Checkout sozlamalarida</a> mavjud.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Bu parametr Fluid Checkout’da boshqariladi. Fluid Checkout yoqilganda, yetkazib berish manzili har doim “Mijozning yetkazib berish manzili uchun standart” ga o‘rnatiladi. Mijozlar to‘lov vaqtida turli yetkazib berish va to‘lov manzillarini taqdim etishlari mumkin.<br><br> Standart to&#39;lov manzilini yetkazib berish manzili bilan bir xil qilib sozlash imkoniyati WooCommerce &gt; Sozlamalar &gt; Fluid Checkout bo&#39;limida mavjud.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Ushbu sozlamalar WP Admin &gt; Fluid Checkout &gt; Sozlamalar bo&#39;limiga ko&#39;chirildi.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Ushbu WooCommerce sozlamalari yorlig&#39;i eskirgan va Fluid Checkout 6.0 da olib tashlanadi.','Go to settings page' => 'Sozlamalar sahifasiga o&#39;ting','Hide this tab permanently' => 'Bu yorliqni butunlay yashirish','Site report preview' => 'Sayt hisobotini oldindan ko&#39;rish','This is the data that would be included in the next site environment report based on your current settings.' => 'Bu sizning joriy sozlamalaringiz asosida keyingi sayt muhiti hisobotiga kiritiladigan ma&#39;lumotlar.','Loading report preview...' => 'Hisobotga oldindan ko&#39;rish yuklanmoqda...','Could not load the site report preview. Try again.' => 'Sayt hisobotining oldindan ko&#39;rish versiyasini yuklab bo&#39;lmadi. Qaytadan urinib ko&#39;ring.','Could not send the site report. Try again.' => 'Sayt hisobotini yuborib bo&#39;lmadi. Qaytadan urinib ko&#39;ring.','Site report sent successfully.' => 'Sayt hisoboti muvaffaqiyatli yuborildi.','Enable and send now' => 'Yoqing va hozir yuboring','Close' => 'Yopish','A site report request is already in progress. Try again in a moment.' => 'Sayt hisoboti so&#39;rovi allaqachon bajarilmoqda. Birozdan keyin qayta urinib ko&#39;ring.','Site environment reporting is disabled.' => 'Sayt muhiti haqida hisobot berish o&#39;chirib qo&#39;yilgan.','No site report data is available to send.' => 'Yuborish uchun sayt hisoboti ma&#39;lumotlari mavjud emas.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Ushbu sayt domeni atrof-muhit hisobotlarini yubora olmaydi (mahalliy yoki ishlab chiqish domenlari bundan mustasno).','A site report was sent recently. Try again later.' => 'Yaqinda sayt hisoboti yuborildi. Keyinroq qayta urinib ko&#39;ring.','The site report could not be sent. Try again later.' => 'Sayt hisobotini yuborib bo&#39;lmadi. Keyinroq qayta urinib ko&#39;ring.','Site environment reporting is not available.' => 'Sayt muhiti haqida hisobot mavjud emas.','No site report data is available for the selected settings.' => 'Tanlangan sozlamalar uchun sayt hisoboti ma&#39;lumotlari mavjud emas.','You are not allowed to manage site reports.' => 'Siz sayt hisobotlarini boshqarish huquqiga ega emassiz.','PRO feature' => 'PRO xususiyati','Other plugins' => 'Boshqa plaginlar','Get only this add-on &mdash; %s' => 'Faqat ushbu qo&#39;shimchani oling — %s','Install add-on' => 'Qo&#39;shimcha dasturni o&#39;rnatish','Upgrade to PRO &mdash; %s' => 'PRO ga yangilang — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'Ushbu parametrlarni ochish uchun <a target="_blank" href="%1$s">%2$s oling</a> .','Add-on' => 'Qo&#39;shish, qo&#39;shimcha; qo&#39;shimcha komponent','View documentation' => 'Hujjatlarni ko&#39;rish','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'So&#39;rovlar uchun tizimga kirgan WordPress foydalanuvchisi kerak bo&#39;ladi. Joriy foydalanuvchi ma&#39;lumotlaridan foydalanish uchun user_id ni qoldiring yoki qo&#39;ng&#39;iroq qiluvchi o&#39;sha foydalanuvchini tahrirlay olganda (edit_user imkoniyati) boshqa hisobga yo&#39;naltirish uchun user_id ni uzating. Tasdiqlanmagan so&#39;rovlar fc_api_forbidden qaytaradi. Noto&#39;g&#39;ri user_id fc_api_user_not_found qaytaradi.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'Qayta ishlash vositasi foydali yukni qaytarganda, HTTP 200 {&quot;data&quot;: { ... } } bilan.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'Hech qanday foydali yuklama bo&#39;lmaganda (masalan, DELETE) HTTP 200 {&quot;success&quot;: true} bilan.','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Xatoliklar WP_Error (kod, xabar, data.status) dan WordPress REST xatosi JSON ni qaytaradi. Sim kodlari fc_api_* prefiksidan foydalanadi.','Forbidden access.' => 'Taqiqlangan kirish.','Target user was not found.' => 'Maqsadli foydalanuvchi topilmadi.','This feature is not available.' => 'Bu funksiya mavjud emas.','A required address field is missing.' => 'Majburiy manzil maydoni yetishmayapti.','Postcode or ZIP is invalid.' => 'Pochta indeksi yoki pochta indeksi noto&#39;g&#39;ri.','Phone number is invalid.' => 'Telefon raqami noto&#39;g&#39;ri.','State or county is invalid.' => 'Shtat yoki okrug noto&#39;g&#39;ri.','Country is invalid or has no address fields.' => 'Mamlakat noto&#39;g&#39;ri yoki manzil maydonlari yo&#39;q.','The request could not be processed.' => 'So&#39;rovni qayta ishlash imkoni bo&#39;lmadi.','Back to previous step' => 'Oldingi bosqichga qaytish','Skip to settings' => 'Sozlamalarga o&#39;tish','Start over and return to the first guided setup step' => 'Qaytadan boshlang va birinchi ko&#39;rsatmali sozlash bosqichiga qayting','Start over' => 'Qaytadan boshlang','Please complete all sub-steps before continuing.' => 'Davom etishdan oldin barcha kichik bosqichlarni bajaring.','Expand' => 'Kengaytirish','Collapse' => 'Yig&#39;ish','Skip' => 'O&#39;tkazib yuborish','Mark as complete' => 'Bajarilgan deb belgilash','Mark as incomplete' => 'Tugallanmagan deb belgilash','View full-size image: %s' => 'To&#39;liq o&#39;lchamli rasmni ko&#39;rish: %s','Full-size setup guide image' => 'To&#39;liq o&#39;lchamli o&#39;rnatish qo&#39;llanmasi tasviri','Close image' => 'Rasmni yopish','Fluid Checkout Guided Setup' => 'Suyuqlikni tekshirish bo&#39;yicha qo&#39;llanma','Welcome' => 'Xush kelibsiz','Explore your checkout' => 'Kassangizni 